"""Original coagulation chapter, first half: bleeding and laboratory interpretation."""
from qbank_authoring import question,ref,finalize
WF=ref('WFH Guidelines for the Management of Hemophilia, Third Edition','https://www1.wfh.org/publication/files/pdf-1863.pdf')
VW=ref('ASH ISTH NHF WFH Guidelines on VWD Management','https://pmc.ncbi.nlm.nih.gov/articles/PMC7805326/')
AH=ref('International Recommendations on Acquired Hemophilia A','https://pmc.ncbi.nlm.nih.gov/articles/PMC7327664/')
AC=ref('ACC Expert Consensus: Management of Anticoagulant-Related Bleeding','https://www.acc.org/latest-in-cardiology/ten-points-to-remember/2020/07/10/11/26/2020-acc-expert-consensus-decision-pathway-on-bleeding')
AX=ref('FDA Safety Communication: Andexxa Benefit-Risk and End of US Sales, December 2025','https://www.fda.gov/safety/medical-product-safety-information/update-safety-andexxa-astrazeneca-fda-safety-communication')
LI=ref('AASLD: Peri-Procedural Bleeding Risk in Cirrhosis','https://www.aasld.org/liver-fellow-network/core-series/clinical-pearls/peri-procedural-management-bleeding-risk-cirrhosis')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A patient has lifelong bleeding, isolated prolonged PT, normal aPTT and correction on mixing. Which single-factor deficiency best fits?', 'Factor VII deficiency',[
 ('Factor VIII deficiency','It usually prolongs aPTT rather than isolated PT.'),('Factor IX deficiency','It affects the intrinsic-pathway assay.'),('Factor XIII deficiency','Routine PT and aPTT are usually normal.')],
 'Use the screening-test pattern to select factor assays', '**Factor VII is assessed by the extrinsic-pathway PT assay.**',['A corrected mixing test supports a deficiency pattern.','Vitamin K deficiency, liver disease and medicines remain acquired alternatives.'], '**Confirm with a factor assay and clinical context.**',['One abnormal screening test is not a complete etiological diagnosis.','Check specimen quality and anticoagulant exposure.'],[['VII','PT'],['VIII or IX','aPTT'],['XIII','Usually neither routine test']],[WF])
q('An isolated prolonged aPTT corrects immediately and after incubation with normal plasma; anticoagulant interference is excluded. Which interpretation is strongest?', 'A coagulation-factor deficiency pattern requiring targeted factor assays',[
 ('A time-dependent factor VIII inhibitor is established','Such an inhibitor commonly prevents sustained correction after incubation.'),('Lupus anticoagulant is definitively proven','Mixing correction does not establish it; specific testing is needed.'),('Factor XIII deficiency explains the screening abnormality','Factor XIII deficiency usually leaves aPTT normal.')],
 'Mixing studies distinguish patterns, not final diagnoses', '**Normal plasma can supply a deficient coagulation factor.**',['Assess VIII, IX and XI according to the bleeding phenotype.','Contact-factor deficiencies can markedly prolong aPTT without a bleeding tendency.'], '**Interpret mixing results alongside the clinical history.**',['Laboratory cutoffs and inhibitor strength affect interpretation.','A corrected result does not identify the deficient factor by itself.'],[['Correction','Deficiency pattern'],['Poor correction','Inhibitor or drug pattern'],['Contact factors','Prolongation may occur without bleeding']],[WF,AH])
q('A postpartum woman develops extensive soft-tissue bleeding and isolated prolonged aPTT. A mixing study initially improves but becomes prolonged after incubation. What is most likely?', 'An acquired factor VIII inhibitor',[
 ('Inherited factor VII deficiency','This affects PT and does not explain this time-dependent pattern.'),('Congenital factor XII deficiency','This can prolong aPTT but does not usually cause this bleeding phenotype.'),('Isolated vitamin K deficiency','PT is generally affected and this is not its mixing pattern.')],
 'Acquired hemophilia can appear without a childhood bleeding history', '**Factor VIII autoantibodies can have time-dependent inhibition.**',['Postpartum presentation is recognized.','Skin, muscle and other soft-tissue bleeding are common presentations.'], '**Arrange urgent specialist hemostatic treatment and inhibitor testing.**',['Measure factor VIII activity and inhibitor titer.','Do not delay bleeding control while awaiting all confirmatory results.'],[['History','New bleeding without inherited history'],['Test','Incubation-dependent inhibition'],['Confirmation','VIII activity and inhibitor assay']],[AH],style='clinical_scenario')
q('A patient with recurrent thrombosis has persistent lupus anticoagulant and a prolonged aPTT. Which interpretation is correct?', 'The in-vitro clotting-test prolongation can coexist with an in-vivo thrombotic tendency',[
 ('The prolonged aPTT proves protection against thrombosis','An assay effect does not establish clinical anticoagulation.'),('Every lupus anticoagulant requires factor VIII replacement','Factor deficiency must be demonstrated separately.'),('The result alone establishes acquired hemophilia','A specific factor inhibitor needs separate investigation.')],
 'An anticoagulant assay name does not describe the whole clinical phenotype', '**Lupus anticoagulants interfere with phospholipid-dependent tests.**',['They can be associated with antiphospholipid syndrome.','Bleeding can occur for other reasons, including coexisting inhibitors or hypoprothrombinemia.'], '**Use appropriate confirmatory testing and clinical criteria.**',['Anticoagulants may interfere with testing.','A prolonged aPTT should not automatically preclude needed antithrombotic treatment.'],[['Laboratory','Phospholipid-dependent interference'],['Clinical association','Thrombosis or pregnancy morbidity'],['Bleeding','Investigate additional mechanisms']],[AH])
q('A boy has recurrent hemarthroses, prolonged aPTT, normal PT and reduced factor VIII activity. What is the most likely diagnosis?', 'Hemophilia A',[
 ('Hemophilia B','This is factor IX deficiency.'),('Bernard-Soulier syndrome','It produces an adhesion defect and usually mucocutaneous bleeding.'),('Factor VII deficiency','It characteristically prolongs PT.')],
 'Factor VIII deficiency impairs intrinsic tenase amplification', '**Hemophilia A is usually X-linked.**',['Severity relates to baseline factor activity.','Women can also have clinically important low factor activity and bleeding.'], '**Manage with a comprehensive hemophilia team.**',['Preventive treatment reduces joint injury.','Assay choice must account for replacement products and nonfactor therapies.'],[['A','Factor VIII'],['B','Factor IX'],['Typical severe phenotype','Deep bleeding and hemarthrosis']],[WF],style='clinical_scenario')
q('Which deficient protein causes hemophilia B?', 'Factor IX',[
 ('Factor VIII','Its deficiency causes hemophilia A.'),('Factor XI','Its deficiency has a different inheritance and bleeding pattern.'),('VWF','Its deficiency or dysfunction causes von Willebrand disease.')],
 'Similar joint-bleeding phenotypes can have different factor defects', '**Factor IX participates in intrinsic tenase with activated VIII.**',['A deficient IX assay distinguishes B from A.','Routine PT is usually normal.'], '**Identify the actual factor before selecting replacement.**',['Inhibitors and treatment history alter management.','Avoid inferring the diagnosis solely from the aPTT magnitude.'],[['Hemophilia B','IX'],['Hemophilia A','VIII'],['Tenase','IXa with VIIIa activates X']],[WF])
q('A child has delayed umbilical-stump bleeding and recurrent delayed postoperative bleeding despite normal PT and aPTT. Which deficiency should be considered?', 'Factor XIII deficiency',[
 ('Severe factor VIII deficiency','aPTT is usually prolonged.'),('Severe factor VII deficiency','PT is usually prolonged.'),('Severe factor X deficiency','Both routine pathways can be prolonged.')],
 'Routine clot-time assays do not measure every step of clot integrity', '**Factor XIII cross-links fibrin after initial clot formation.**',['Deficiency can cause delayed bleeding and impaired wound healing.','Intracranial bleeding is an important risk in severe congenital disease.'], '**Request a specific factor XIII activity assay.**',['A normal screening coagulation panel does not exclude the disorder.','Use specialist replacement and preventive planning when confirmed.'],[['PT/aPTT','Initial clot generation'],['XIII','Fibrin stabilization'],['Clue','Delayed bleeding with normal screening tests']],[WF],style='clinical_scenario')
q('Which description best defines type 1 von Willebrand disease?', 'A partial quantitative deficiency of VWF',[
 ('A complete absence of VWF','That is type 3.'),('A qualitative VWF–platelet gain-of-binding defect','That characterizes type 2B.'),('An isolated inherited factor IX deficiency','That is hemophilia B.')],
 'VWF quantity and function define different disease categories', '**VWF supports platelet adhesion and carries factor VIII.**',['Type 1 reduces the available amount.','Type 2 comprises qualitative subtypes and type 3 severe quantitative deficiency.'], '**Interpret activity, antigen and factor VIII together.**',['Stress, pregnancy and inflammation can alter levels.','Bleeding history and repeat testing in a suitable state may be necessary.'],[['Type 1','Partial quantitative'],['Type 2','Qualitative'],['Type 3','Near-complete quantitative absence']],[VW])
q('A patient has disproportionately low factor VIII with impaired VWF binding to VIII. Which VWD subtype can mimic hemophilia A?', 'Type 2N',[
 ('Type 2B','Its characteristic problem is enhanced platelet binding.'),('Type 2A','Loss of high-molecular-weight multimers is characteristic.'),('Type 1','It is primarily a partial quantitative deficiency.')],
 'The factor VIII carrier interaction matters diagnostically', '**Type 2N impairs VWF binding and stabilization of factor VIII.**',['Inheritance and specialized binding studies help distinguish it from hemophilia A.','Routine VWF platelet-binding activity may not explain the low VIII alone.'], '**Select targeted VWF studies when the phenotype is discordant.**',['Genetic testing can support classification.','Treatment planning depends on correcting the relevant VWF/VIII problem.'],[['2N','VIII binding'],['2B','Enhanced platelet binding'],['Hemophilia A','F8-related VIII deficiency']],[VW,WF])
q('Which statement about desmopressin in VWD is most accurate?', 'Response assessment is useful in suitable patients, and fluid restriction is needed because of hyponatremia risk',[
 ('It is the preferred routine treatment for type 2B','It is generally contraindicated because it can worsen thrombocytopenia.'),('It reliably replaces absent VWF in type 3','It is ineffective in type 3 because adequate stores are absent.'),('Repeated doses eliminate the need to monitor sodium','Water retention and tachyphylaxis remain concerns.')],
 'Mobilizing endogenous stores requires the right subtype and safety plan', '**Desmopressin releases stored VWF and factor VIII.**',['A response trial guides use where appropriate.','Major surgery often requires a broader hemostatic plan.'], '**Restrict free water and assess contraindications.**',['Account for cardiovascular disease and other patient-specific risks.','Use VWF concentrate when desmopressin is unsuitable or inadequate.'],[['Suitable responder','Potential use in selected type 1 disease'],['Type 2B','Generally avoid'],['Safety','Hyponatremia and fluid restriction']],[VW])
q('A patient receiving emicizumab needs measurement of infused factor VIII activity. Which assay approach is appropriate?', 'A validated chromogenic factor VIII assay using bovine reagents',[
 ('Routine aPTT as a quantitative factor VIII measure','Emicizumab shortens aPTT and makes this misleading.'),('An unmodified aPTT-based one-stage VIII assay','It can overestimate activity in the presence of emicizumab.'),('PT/INR converted directly to factor VIII activity','PT does not quantify factor VIII.')],
 'Nonfactor prophylaxis changes the meaning of familiar coagulation assays', '**Emicizumab bridges IXa and X and mimics VIII cofactor function.**',['Its activity is not equivalent to a normal factor VIII concentration.','Human-reagent and bovine-reagent chromogenic assays behave differently.'], '**Tell the laboratory about treatment before ordering tests.**',['Use an appropriate assay for inhibitors and replacement monitoring.','Avoid interpreting normalized aPTT as absence of bleeding risk.'],[['aPTT','Artificially shortened'],['Bovine chromogenic VIII','Useful for VIII assessment'],['Clinical care','Treatment-aware assay selection']],[WF],style='clinical_scenario')
q('A woman with acquired hemophilia A has an expanding muscle hematoma and falling hemoglobin. What is the best management principle?', 'Urgent specialist bleeding control with an appropriate bypassing agent or recombinant porcine VIII, plus a plan to eradicate the inhibitor',[
 ('Delay hemostatic treatment until the inhibitor disappears spontaneously','Severe active bleeding requires immediate management.'),('Treat only with vitamin K because aPTT is prolonged','Vitamin K does not remove the VIII autoantibody.'),('Use desmopressin alone for all severe acquired-inhibitor bleeding','It is inadequate for this high-risk presentation.')],
 'Hemostasis and inhibitor eradication are distinct treatment goals', '**Severe acquired-inhibitor bleeding needs an effective specialist agent.**',['Choice considers availability, thrombosis risk and laboratory monitoring.','Immunosuppression is tailored to inhibitor burden and patient vulnerability.'], '**Assess bleeding clinically rather than relying on aPTT alone.**',['Monitor hemoglobin, imaging and compartment effects as indicated.','Avoid unnecessary invasive procedures during uncontrolled bleeding.'],[['Immediate','Bleeding control'],['Longer term','Inhibitor eradication'],['Monitoring','Clinical response and agent-specific tests']],[AH],style='clinical_scenario')
q('A warfarin-treated patient has life-threatening bleeding with elevated INR. Which reversal strategy is generally preferred?', 'Four-factor PCC with intravenous vitamin K, alongside source control and resuscitation',[
 ('Intravenous vitamin K alone as the fastest complete reversal','Its onset is slower and does not provide immediate factor replacement.'),('Idarucizumab','It specifically reverses dabigatran.'),('Protamine as complete warfarin reversal','It targets heparin, not the vitamin K antagonist mechanism.')],
 'Immediate factor replacement and sustained reversal serve different purposes', '**Four-factor PCC rapidly supplies vitamin K-dependent factors.**',['Vitamin K supports subsequent endogenous synthesis.','Dose and monitoring follow INR, product and institutional protocol.'], '**Treat the patient and bleeding source at the same time.**',['Consider volume and thrombosis risks.','Reassess the indication and timing for restarting anticoagulation after control.'],[['PCC','Rapid replacement'],['IV vitamin K','Sustained recovery'],['Resuscitation','Hemodynamic and source management']],[AC],style='clinical_scenario')
q('Which specific reversal agent is used for dabigatran in life-threatening or uncontrolled bleeding?', 'Idarucizumab',[
 ('Protamine','It reverses heparin rather than directly binding dabigatran.'),('Vitamin K','It reverses vitamin K antagonist effects.'),('Andexanet alfa','It was developed for selected factor Xa inhibitors, not dabigatran.')],
 'Match the antidote to the anticoagulant mechanism', '**Idarucizumab binds dabigatran and its active metabolites.**',['Renal dysfunction can prolong exposure.','Rebound anticoagulant effect can require reassessment in selected cases.'], '**Use drug-aware laboratory assessment when available.**',['Dilute thrombin time or ecarin-based tests can be informative.','A routine INR is not a quantitative dabigatran assay.'],[['Dabigatran','Direct thrombin inhibitor'],['Idarucizumab','Specific binding reversal'],['Assessment','Timing, renal function and suitable tests']],[AC])
q('In November 2026, which statement about reversing factor Xa inhibitor-associated life-threatening bleeding correctly accounts for US availability?', 'Andexxa US sales ended in December 2025; use the currently available local reversal protocol, often including four-factor PCC when appropriate',[
 ('Andexxa remains routinely sold throughout the US without a safety change','FDA reported an unfavorable benefit-risk assessment and the end of US sales.'),('Vitamin K directly neutralizes apixaban','It does not reverse direct factor Xa inhibition.'),('Idarucizumab specifically binds rivaroxaban','It is specific for dabigatran.')],
 'Older antidote algorithms must be checked against current safety and availability', '**FDA reported the end of US Andexxa manufacture and sales after December 22, 2025.**',['Thromboembolic risk contributed to the benefit-risk concern.','Availability and approved practice can differ across jurisdictions.'], '**Follow a current institutional emergency pathway.**',['Stop the anticoagulant, control bleeding and assess recent exposure and renal function.','Four-factor PCC is a nonspecific strategy with its own thrombotic risk.'],[['Older algorithm','May list andexanet'],['US 2026','Sales discontinued'],['Current action','Available protocol and urgent specialist care']],[AX,AC])
q('A stable patient with cirrhosis has INR 1.8 before paracentesis, without active bleeding or another indication. What is the best interpretation?', 'INR alone does not predict procedural bleeding, and prophylactic plasma solely to normalize it is not recommended',[
 ('The INR proves effective protection against venous thrombosis','Cirrhosis can produce both bleeding and thrombosis.'),('Plasma to a normal INR is mandatory before every low-risk procedure','Routine correction is not recommended and can cause harm.'),('The INR precisely measures all anticoagulant and procoagulant changes','It does not capture the rebalanced system.')],
 'Cirrhosis changes both sides of the coagulation balance', '**INR measures selected procoagulant effects and is not a global bleeding-risk measure.**',['Portal pressure, procedure type and acute illness matter.','Plasma can add volume and worsen portal pressure.'], '**Use procedure-specific and patient-specific assessment.**',['Active bleeding requires a separate management pathway.','Do not generalize this reasoning to warfarin reversal.'],[['Cirrhosis INR','Incomplete hemostatic picture'],['Low-risk procedure','No routine INR normalization'],['Bleeding assessment','Clinical and procedural context']],[LI],style='clinical_scenario')

if __name__=='__main__':print('Bleeding coagulation: '+str(len(rows))+' questions drafted')
